/** Generated by tools/version.mjs from extension/manifest.json and CHANGELOG.txt. */
export const EXTENSION_DISPLAY_NAME = "LPC Companion";
export const EXTENSION_VERSION = "0.2.1";
export const CHANGELOG_TEXT = "LPC Companion — What's New\n==========================\n\nVersion 0.2.1 (2026-11-11)\n--------------------------\nAI Presets & Extension Compatibility:\n- Works cleanly with assistant-prefill presets: Companion appearance updates now stay ahead of trailing assistant prefills and reasoning starters so community presets and strict chat providers accept requests without role-order errors.\n- Leaves background memory extensions undisturbed: Summarizer, memory, and quiet background prompts now run without companion instructions or avatar tools, while preserving message metadata used by third-party memory extensions.\n- Clearer preset readiness guidance: Turning on model tool calls now warns right in settings when your active SillyTavern preset has function calling turned off or uses a prompt post-processing mode that strips tools.\n- Smarter scene backdrop updates: Improved scene-tool guidance so models switch between woodland, hearth, courtyard, and plain backdrops more reliably when the story moves to a new location or time of day.\n\nWardrobe, Party & Mobile Polish:\n- Smooth support for classic sleeveless garments: Importing or equipping classic garments that ship walking art without a separate standing-idle sheet now automatically selects a matching standing frame and explains the adjustment.\n- Remove extra companions right from Party view: Added a confirmation-guarded \"Remove from chat\" button directly inside the shared companion workspace (leaving the original character card untouched) alongside clearer management labels.\n- Steady companion size when pinch-zooming: Zooming in to read chat text on phones or trackpads now keeps floating companion panels and compact launchers comfortably sized instead of enlarging them over the conversation.\n\nVersion 0.2.0 (2026-11-10)\n--------------------------\nPerformance & Memory:\n- Much faster startup: SillyTavern loads the extension significantly faster, and your companion appears almost immediately when opening a chat while using noticeably less memory in the background.\n\nCharacter Closet & Studio:\n- Closet & Pose lists save with your character: Your saved Closet pieces and custom Pose/Mood lists are now stored directly with your character and chat—and travel with exported character files—rather than staying tied to a single browser.\n- Safe Studio canceling: Closing or canceling the Wardrobe Studio now cleanly discards any trial Closet, color, or pose-list tweaks without changing your saved character.\n- Accurate item descriptions: Updated Studio labels so wardrobe counts reflect only the items actually included in the extension.\n\nInterface & Theme Polish:\n- Cleaner theme-matching controls: Refreshed buttons, tabs, collapsible sections, and color-swatch menus so they blend smoothly into light, dark, and high-contrast SillyTavern themes.\n- Clearer pose restrictions: Unavailable poses and controls now look clearly inactive and explain right alongside the button when a worn item (such as a cape) prevents an action.\n- Better small-screen & large-text fit: Fixed clipped item names in the Studio list and improved wrapping on narrow phone screens and larger font sizes.\n- More compact starter outfit editor: Placed the four-angle character preview in a single row at the top so your named outfits and clothing color choices stay visible without extra scrolling.\n- Built-in What's New notes and troubleshooting log: Check your installed version, read release highlights, or copy and download a privacy-safe diagnostic report right from LPC Companion settings.\n- Simpler extension name: Listed as \"LPC Companion\" in Manage Extensions with standard version numbers starting at 0.2.0.\n";

export function parseChangelog(text) {
    const entries = [];
    let current = null;
    let group = null;
    for (const rawLine of String(text ?? '').split(/\r?\n/)) {
        const line = rawLine.trim();
        if (!line || /^[=\-]{3,}$/.test(line) || line.startsWith('LPC Companion —')) continue;
        const versionMatch = /^Version\s+([^\s]+)(?:\s*\(([^)]+)\))?$/.exec(line);
        if (versionMatch) {
            current = {
                version: versionMatch[1],
                date: versionMatch[2] ?? '',
                groups: [],
            };
            entries.push(current);
            group = null;
            continue;
        }
        if (!current) continue;
        if (line.startsWith('- ')) {
            if (!group) {
                group = { heading: '', items: [] };
                current.groups.push(group);
            }
            group.items.push(line.slice(2).trim());
        } else if (line.endsWith(':')) {
            group = { heading: line.slice(0, -1).trim(), items: [] };
            current.groups.push(group);
        }
    }
    return entries.map(entry => Object.freeze({
        version: entry.version,
        date: entry.date,
        groups: Object.freeze(entry.groups.filter(g => g.items.length > 0).map(g => Object.freeze({
            heading: g.heading,
            items: Object.freeze(g.items),
        }))),
    }));
}

export const CHANGELOG_ENTRIES = Object.freeze(parseChangelog(CHANGELOG_TEXT));
